/* Lot 90: the background shorthand split into its longhands, and the cascade of those longhands in the reader sheet (generated by scripts/lot90_gen.py; expectations from that model). */

#include "../../framework/unity.h"
#include <string.h>
#include "wf_sitecss.h"
#include "wf_cssbg.h"

static wf_site_t g_d;
static char g_o[1400];
static wf_cssbg_t g_bg;

static const char *style_of(const char *html, const char *id) {
    int i;
    if (wf_site_prepare(&g_d, html, (int)strlen(html)) != 0) return "PREPARE FAILED";
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) { wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o)); return g_o; }
    return "NO SUCH ID";
}

static void test_l90_short_0(void) {
    TEST_ASSERT_EQUAL(1, wf_cssbg_shorthand("-1110px 738% / aUto  0 nonE,	-111px 	 969% / auTO	auto	#55e	no-repeat repEaT", &g_bg));
    TEST_ASSERT_EQUAL(2, g_bg.layers);
    TEST_ASSERT_EQUAL(1, g_bg.has_image);
    TEST_ASSERT_EQUAL_STRING("none, none", g_bg.image);
    TEST_ASSERT_EQUAL(1, g_bg.has_position);
    TEST_ASSERT_EQUAL_STRING("-1110px 738%, -111px 969%", g_bg.position);
    TEST_ASSERT_EQUAL(1, g_bg.has_size);
    TEST_ASSERT_EQUAL_STRING("auto 0, auto", g_bg.size);
    TEST_ASSERT_EQUAL(1, g_bg.has_repeat);
    TEST_ASSERT_EQUAL_STRING("repeat, repeat-y", g_bg.repeat);
    TEST_ASSERT_EQUAL_STRING("#55e", g_bg.color);
}

